nta.declaration:
// A second page (the Mac) loads the save while the phone's reply is still being generated by a SERVER job.
// src/ts/process/emptyReply.ts settleCharacterOnLoad: the chat is settled (last reply marked "cut off", isStreaming=false) unless
// the character's streamingAt stamp is younger than STREAM_ALIVE_MS = 45 s. The stamp is refreshed by a setInterval of 15 s in the
// generating page (index.svelte.ts:1700-1715) and reaches the server with that page's autosave. A locked iPhone freezes the page's
// timers; the server job keeps running (jobStore.cjs). Time unit: seconds.
const int BEAT = 15;       // STREAM_BEAT_MS
const int ALIVE = 45;      // STREAM_ALIVE_MS
const int JOBMIN = 7;      // measured: no-reasoning reply 7.5 s
const int JOBMAX = 120;    // measured: grok first word after 119 s
const bool LOCKS = false;   // the phone may lock its screen
const bool FIX = false;       // the code since F2: the loader asks GET /proxy-stream-jobs/running whether a job for this chat runs
const bool DIES = false;     // the phone page may die (Safari swiped away)
bool running = true;
clock s;     // age of the newest stamp that reached the server
clock b;     // beat timer of the generating page
clock j;     // age of the server job
